callbacks.upstream_source:
.recipe((c, p) -> {
                p.shaped(RecipeCategory.MISC, c.get(), 1)
                    .pattern("N")
                    .pattern("A")
                    .define('N', Items.IRON_NUGGET)
                    .define('A', AllItems.ANDESITE_ALLOY)
                    .unlockedBy("has_ingredient", RegistrateRecipeProvider.has(AllItems.ANDESITE_ALLOY))
                    .save(p);
                p.shapeless(RecipeCategory.MISC, c.get(), 1)
                    .requires(SimTags.Items.HANDLE_VARIANTS)
                    .unlockedBy("has_ingredient", p.has(SimTags.Items.HANDLE_VARIANTS))
                    .save(p, Simulated.path("handle_undye").toString());
            })

.recipe((c, p) -> {
                        p.shapeless(RecipeCategory.MISC, c.get(), 2)
                                .requires(AllBlocks.CHUTE)
                                .requires(AllBlocks.SHAFT)
                                .requires(AllItems.IRON_SHEET)
                                .unlockedBy("has_ingredient", RegistrateRecipeProvider.has(AllItems.IRON_SHEET))
                                .save(p);

                        p.shapeless(RecipeCategory.MISC, c.get(), 1)
                                .requires(SimBlocks.AUGER_COG.get())
                                .unlockedBy("has_ingredient", RegistrateRecipeProvider.has(AllItems.IRON_SHEET))
                                .save(p, Simulated.path(c.getName() + "_from_auger_cogwheel").toString());
                    })

.blockstate((c, p) -> p.getVariantBuilder(c.get()).forAllStates(state -> {
                        final String suffix = state.getValue(AnalogTransmissionBlock.POWERED) ? "_on" : "";
                        final Identifier path = Simulated.path("block/" + c.getName() + "/block" + suffix);
                        final Direction.Axis axis = state.getValue(AnalogTransmissionBlock.AXIS);
                        return new ConfiguredModel[]{
                                ConfiguredModel.builder()
                                        .modelFile(p.models().getExistingFile(path))
                                        .rotationX(axis == Direction.Axis.Y ? 0 : 90)
                                        .rotationY(axis == Direction.Axis.X ? 90 : 0)
                                        .build()};
                    }))

.recipe((c, p) -> {
                        p.shapeless(RecipeCategory.MISC, c.get(), 2)
                                .requires(AllBlocks.SAIL.white())
                                .requires(AllBlocks.SAIL.white())
                                .unlockedBy("has_ingredient", RegistrateRecipeProvider.has(AllBlocks.SAIL.white()))
                                .save(p);

                        p.shapeless(RecipeCategory.MISC, AllBlocks.SAIL.white(), 1)
                                .requires(c.get().asItem())
                                .unlockedBy("has_ingredient", RegistrateRecipeProvider.has(c.get()))
                                .save(p);
                    })

.blockstate((c, p) -> {
                        final var model = p.models()
                                .withExistingParent(colorName + "_symmetric_sail",
                                        p.modLoc("block/symmetric_sail/block"))
                                .texture("0", Identifier.fromNamespaceAndPath(Create.MOD_ID, "block/sail/canvas_" + colorName))
                                .texture("1", p.modLoc("block/symmetric_sail/side_" + colorName))
                                .texture("particle", Identifier.fromNamespaceAndPath(Create.MOD_ID, "block/sail/canvas_" + colorName));
                        SimBlockStateService.INSTANCE.genericModelBuilder(
                                c,
                                p,
                                SimBlockStateGen::xySymmetricSail,
                                blockState -> model
                        );
                    })

.blockstate((ctx, prov) -> prov.horizontalBlock(ctx.get(), state -> {
                    NameplateBlock.Position position = state.getValue(NameplateBlock.POSITION);
                    return prov.models()
                            .withExistingParent(colorName + "_nameplate_" + position.getSerializedName(), prov.modLoc("block/nameplate/block_" + position.getSerializedName()))
                            .texture("0", Simulated.path("block/nameplate/" + colorName + "_nameplate"))
                            .texture("particle", Simulated.path("block/nameplate/" + colorName + "_nameplate"));
                }))

.recipe((c, p) -> {
                        if (color == DyeColor.WHITE) {
                            p.shapeless(RecipeCategory.BUILDING_BLOCKS, c.get(), 4)
                                    .requires(Items.PAPER)
                                    .requires(Items.STICK)
                                    .requires(AllItems.ANDESITE_ALLOY)
                                    .unlockedBy("has_ingredient", RegistrateRecipeProvider.has(AllItems.ANDESITE_ALLOY))
                                    .save(p);
                        }
                        p.shapeless(RecipeCategory.BUILDING_BLOCKS, c.get())
                                .requires(SimTags.DYE_MAP.get(colorName))
                                .requires(SimTags.Items.NAMEPLATE_ITEMS)
                                .unlockedBy("has_nameplate", p.has(SimTags.Items.NAMEPLATE_ITEMS))
                                .save(p, Simulated.path("crafting/" + c.getName() + "_from_other_nameplate").toString());
                    })

.blockstate((ctx, prov) -> {
            SimBlockStateService.INSTANCE.directionalAxisBlock(ctx, prov, (blockState, vertical) -> {
                final String suffix = vertical ? "vertical" : "horizontal";
                if(variant == HandleBlock.Variant.IRON) {
                    return prov.models()
                            .getExistingFile(prov.modLoc("block/handle/block_" + suffix));
                } else {
                    return prov.models()
                            .withExistingParent(ctx.getName() + "_" + suffix, prov.modLoc("block/handle/block_" + suffix))
                            .texture("0", prov.modLoc("block/handle/" + name));
                }
            });
        })

.blockstate((c, p) -> {
                final ModelBuilder model = p.models()
                        .withExistingParent(c.getName(), "block/cube_all")
                        .texture("all", p.modLoc("block/envelope_block/envelope_" + DyeColor.WHITE.getName()));
                p.simpleBlock(c.get(), model);
            })

.blockstate((c, p) -> {
                        final ModelBuilder model = p.models()
                                .withExistingParent(c.getName(), "block/cube_all")
                                .texture("all", p.modLoc("block/envelope_block/envelope_" + colorName));
                        p.simpleBlock(c.get(), model);
                    })

.blockstate((ctx, prov) ->
                            BlockStateGen.simpleBlock(ctx, prov,
                                    blockState -> prov.models().getExistingFile(
                                            prov.modLoc("block/" + ctx.getName() + "/block_" + blockState.getValue(HotAirBurnerBlock.VARIANT).getSerializedName()))
                            )
                    )
